import { useState } from "react";
import { Button, DecisionOptionCard, FieldFrame, PageHeader, RecordList, Select, StatusPill, Tag, Typography } from "@autograph/components";
import { DataTableComposition, RecordDetailPanel, RecordListDetailLayout, StepRailComposition } from "@autograph/compositions";

type Step = "mapping" | "preview" | "review";
type Row = { id:string; vendorRaw:string; amount:number; currency:string; transactionDate:string; issue:string; sourceRef:string; candidates:{id:string;title:string;description:string}[] };
const rows: Row[] = [
{id:"TX-042",vendorRaw:"Northstar Cloud Inc.",amount:12950,currency:"USD",transactionDate:"2026-08-31",issue:"Two candidate vendor identities",sourceRef:"AP-4192",candidates:[{id:"nsc-1008",title:"Northstar Cloud, Inc.",description:"Vendor NSC-1008 · Same legal name and USD payment profile"},{id:"nsc-2041",title:"Northstar Cloud Services LLC",description:"Vendor NSC-2041 · Similar alias; different legal entity"}]},
{id:"TX-039",vendorRaw:"Atlas Office Supply",amount:486.2,currency:"USD",transactionDate:"2026-08-29",issue:"Possible duplicate source reference",sourceRef:"AP-4187",candidates:[{id:"distinct",title:"Keep as a distinct transaction",description:"Amount differs from the earlier Atlas row by USD 14.00"},{id:"duplicate",title:"Mark as duplicate",description:"Exclude after a human confirms the source document"}]},
{id:"TX-040",vendorRaw:"Brightline Travel",amount:2280,currency:"USD",transactionDate:"2026-08-30",issue:"Cost center is missing",sourceRef:"AP-4189",candidates:[{id:"sales",title:"Sales · CC-210",description:"Candidate based on source description; requires confirmation"},{id:"ops",title:"Operations · CC-320",description:"Used on the previous Brightline invoice"}]},
{id:"TX-041",vendorRaw:"Harbor Freight Services",amount:9150,currency:"USD",transactionDate:"2026-09-01",issue:"Date is outside the August batch period",sourceRef:"AP-4190",candidates:[{id:"keep",title:"Keep September 1",description:"Route the row to the September period"},{id:"correct",title:"Correct to August 31",description:"Use only if the source invoice confirms August 31"}]}
];
const allPreview = [
{id:"TX-001",vendor:"Acme Industrial",amount:"$1,240.00",date:"2026-08-03",sourceRef:"AP-4101",result:"Ready"},
{id:"TX-018",vendor:"Cedar Labs",amount:"$780.50",date:"2026-08-17",sourceRef:"AP-4148",result:"Ready"},
{id:"TX-039",vendor:"Atlas Office Supply",amount:"$486.20",date:"2026-08-29",sourceRef:"AP-4187",result:"Needs review"},
{id:"TX-040",vendor:"Brightline Travel",amount:"$2,280.00",date:"2026-08-30",sourceRef:"AP-4189",result:"Needs review"},
{id:"TX-041",vendor:"Harbor Freight Services",amount:"$9,150.00",date:"2026-09-01",sourceRef:"AP-4190",result:"Needs review"},
{id:"TX-042",vendor:"Northstar Cloud Inc.",amount:"$12,950.00",date:"2026-08-31",sourceRef:"AP-4192",result:"Needs review"}
];
const targetOptions = [{value:"vendorRaw",label:"Vendor name"},{value:"amount",label:"Amount"},{value:"currency",label:"Currency"},{value:"transactionDate",label:"Transaction date"},{value:"sourceRef",label:"Source reference"},{value:"ignore",label:"Do not import"}];
const defaults:Record<string,string>={"Vendor":"vendorRaw","Invoice total":"amount","Currency":"currency","Transaction date":"transactionDate","Reference":"sourceRef"};
const money=(n:number,c:string)=>new Intl.NumberFormat("en-US",{style:"currency",currency:c}).format(n);
export default function SpendImportReview(){
 const [step,setStep]=useState<Step>("mapping"); const [mapping,setMapping]=useState(defaults); const [saved,setSaved]=useState(false);
 const [selectedId,setSelectedId]=useState("TX-042"); const [detail,setDetail]=useState(false); const [choices,setChoices]=useState<Record<string,string>>({}); const [outcomes,setOutcomes]=useState<Record<string,"resolved"|"deferred">>({});
 const selected=rows.find(r=>r.id===selectedId)??rows[0]; const choice=choices[selected.id]; const outcome=outcomes[selected.id]; const remaining=rows.filter(r=>!outcomes[r.id]).length;
 const steps=[{id:"mapping",title:"Map fields",subtitle:"Match AP export columns",state:step==="mapping"?"current":"done" as const,statusLabel:step==="mapping"?"Current":"Done"},{id:"preview",title:"Preview changes",subtitle:"38 ready · 4 need review",state:step==="mapping"?"pending":step==="preview"?"current":"done" as const,statusLabel:step==="mapping"?"Pending":step==="preview"?"Current":"Saved"},{id:"review",title:"Review exceptions",subtitle:"Human decisions only",state:step==="review"?"current":"pending" as const,statusLabel:step==="review"?"Current":"Pending"}];
 return <main className="min-h-screen bg-[var(--color-bg-page)] p-[var(--space-6)] text-[var(--color-text-primary)]"><div className="mx-auto grid max-w-[1440px] gap-[var(--space-6)]">
  <PageHeader title="Import AP spend" subtitle="AP export · Batch IMP-88 · 42 synthetic rows · Received Sep 8, 2026 at 14:20 UTC" actions={<StatusPill tone={saved?"success":"info"} label={saved?"Import saved in simulation":"Draft import"}/>}/>
  <div className="grid grid-cols-[280px_minmax(0,1fr)] gap-[var(--space-6)] items-start"><StepRailComposition spec={{type:"step_rail",title:"Import steps",description:"Prepare the batch, preview its effect, then resolve uncertain rows.",config:{steps,activeStepId:step}}}/>
  <section className="grid gap-[var(--space-5)]">
  {step==="mapping"?<div className="rounded-[var(--radius-panel)] border border-[var(--color-border-subtle)] bg-[var(--color-bg-surface)] p-[var(--space-6)] grid gap-[var(--space-5)]">
   <div><Typography as="h2" variant="title">Map AP export fields</Typography><Typography tone="secondary">Confirm how source columns become spend fields. Sample values remain recognizable beside each mapping.</Typography></div>
   <div className="grid gap-[var(--space-4)]">{[{source:"Vendor",sample:"Northstar Cloud Inc."},{source:"Invoice total",sample:"12950"},{source:"Currency",sample:"USD"},{source:"Transaction date",sample:"2026-08-31"},{source:"Reference",sample:"AP-4192"}].map(f=><div key={f.source} className="grid grid-cols-[1fr_40px_1fr] gap-[var(--space-4)] items-end border-b border-[var(--color-border-subtle)] pb-[var(--space-4)]"><div><Typography variant="body-strong">{f.source}</Typography><Typography variant="caption" tone="muted">Sample: {f.sample}</Typography></div><Typography tone="muted">→</Typography><FieldFrame label="Spend field"><Select value={mapping[f.source]} options={targetOptions} onValueChange={v=>setMapping(m=>({...m,[f.source]:v}))}/></FieldFrame></div>)}</div>
   <div className="flex justify-end"><Button variant="primary" onClick={()=>setStep("preview")}>Preview imported changes</Button></div>
  </div>:null}
  {step==="preview"?<div className="grid gap-[var(--space-5)]">
   <div className="rounded-[var(--radius-panel)] border border-[var(--color-border-subtle)] bg-[var(--color-bg-surface)] p-[var(--space-5)] grid gap-[var(--space-4)]"><div className="flex items-start justify-between gap-[var(--space-4)]"><div><Typography as="h2" variant="title">Preview imported changes</Typography><Typography tone="secondary">42 rows will be considered using the confirmed mapping. Six representative rows are shown.</Typography></div><div className="flex gap-[var(--space-2)]"><StatusPill tone="success" label="38 ready"/><StatusPill tone="warning" label="4 need review"/></div></div>
   <DataTableComposition spec={{type:"data_table",config:{ariaLabel:"Preview of imported AP rows",density:"compact",columns:[{id:"id",label:"Row"},{id:"vendor",label:"Vendor"},{id:"amount",label:"Amount",align:"right"},{id:"date",label:"Date"},{id:"sourceRef",label:"Source ref"},{id:"result",label:"Import result"}],rows:allPreview}}}/>
   {!saved?<div className="flex justify-between"><Button variant="secondary" onClick={()=>setStep("mapping")}>Back to mapping</Button><Button variant="primary" onClick={()=>setSaved(true)}>Save import</Button></div>:<div className="rounded-[var(--radius-control)] border border-[var(--color-status-success)] bg-[var(--color-status-success-bg)] p-[var(--space-4)] grid gap-[var(--space-3)]"><Typography variant="body-strong">Import saved in simulation</Typography><Typography>38 rows imported into the simulated spend register. 4 rows remain in human review and were not treated as reconciled.</Typography><div><Button variant="primary" onClick={()=>setStep("review")}>Review 4 exception rows</Button></div></div>}
   </div></div>:null}
  {step==="review"?<RecordListDetailLayout hasSelection={Boolean(selected)} selectedId={selected.id} showDetailOnConstrained={detail} onBack={()=>setDetail(false)} backLabel="Back to exception rows"
   list={({isDetailVisible})=><RecordList ariaLabel="AP rows needing review" heading="Exception rows" summary={`${remaining} remaining`} description="Source evidence and human decisions only." selectedId={isDetailVisible?selected.id:undefined} onSelect={id=>{setSelectedId(id);setDetail(true)}} items={rows.map(r=>({id:r.id,primary:r.vendorRaw,secondary:`${r.id} · ${r.sourceRef} · ${r.transactionDate}`,trailing:<><Typography as="span" variant="body-strong">{money(r.amount,r.currency)}</Typography><StatusPill size="xs" tone={outcomes[r.id]==="resolved"?"success":outcomes[r.id]==="deferred"?"neutral":"warning"} label={outcomes[r.id]==="resolved"?"Resolved":outcomes[r.id]==="deferred"?"Deferred":"Needs review"}/></>}))}/>} detail={<RecordDetailPanel title={selected.vendorRaw} subtitle={`Imported row ${selected.id}`} status={{label:outcome==="resolved"?"Resolved in simulation":outcome==="deferred"?"Deferred in simulation":"Needs review",tone:outcome==="resolved"?"success":outcome==="deferred"?"neutral":"warning"}} metadata={[{id:"batch",label:"Batch",value:"IMP-88"},{id:"source",label:"Source",value:"AP export"}]} sections={[{id:"source",title:"Original source row",items:[{type:"note",id:"note",title:"Source evidence",body:"Preserved as imported; review actions do not rewrite it.",tone:"info"},{type:"field",id:"vendor",label:"Vendor (raw)",value:selected.vendorRaw},{type:"field",id:"amount",label:"Amount",value:`${selected.currency} ${selected.amount.toFixed(2)}`},{type:"field",id:"date",label:"Transaction date",value:selected.transactionDate},{type:"field",id:"ref",label:"Source reference",value:selected.sourceRef}]},{id:"why",title:"Why this row is exceptional",items:[{type:"note",id:"issue",title:selected.issue,body:"A finance operator must choose or leave this unresolved.",tone:"warning"}]},{id:"action",title:"Bounded next action",items:[{type:"note",id:"options",body:"Selections and outcomes are in-memory simulation only.",tone:"neutral"}]}]} renderItem={item=>item.id==="options"?<div className="grid gap-[var(--space-3)]">{selected.candidates.map(c=><DecisionOptionCard key={c.id} name={`choice-${selected.id}`} value={c.id} title={c.title} description={c.description} selected={choice===c.id} density="compact" tag={choice===c.id?<Tag tone="info" size="md">Selected</Tag>:undefined} onSelect={()=>{setChoices(x=>({...x,[selected.id]:c.id}));setOutcomes(x=>{const n={...x};delete n[selected.id];return n})}}/>)}{outcome?<Typography variant="body-strong">{outcome==="resolved"?"Simulated decision recorded.":"Left unresolved for follow-up."}</Typography>:null}</div>:undefined} actions={[{id:"preview",label:"Back to import summary",intent:"secondary"},{id:"defer",label:"Leave unresolved",intent:"secondary"},{id:"apply",label:"Apply simulated decision",intent:"primary-strong",disabled:!choice||Boolean(outcome)}]} onAction={id=>{if(id==="preview")setStep("preview");if(id==="defer")setOutcomes(x=>({...x,[selected.id]:"deferred"}));if(id==="apply"&&choice)setOutcomes(x=>({...x,[selected.id]:"resolved"}))}}/>}/>:null}
  </section></div><Typography variant="caption" tone="muted">Synthetic fixture · All mapping, import, and review changes are in-memory simulations. Automated reconciliation is not represented as shipped behavior.</Typography>
 </div></main>;
}
